def t(k):
    while k % 2 == 0:
        k //= 2
    return k

def h(k):
    # 0 if t(k) ≡ 1 mod 4, 1 if t(k) ≡ 3 mod 4
    return (t(k) % 4 - 1) // 2

# Search for ALL squares in a long prefix
# A square is (n, a) such that h(n+i) == h(n+a+i) for i=0..a-1
N = 100000
flist = [h(k) for k in range(1, N+1)]

squares = []
for a in range(1, 200):
    for n in range(1, N - 2*a + 1):
        ok = True
        for i in range(a):
            if flist[n-1+i] != flist[n-1+a+i]:
                ok = False
                break
        if ok:
            word = tuple(flist[n-1:n-1+a])
            squares.append((a, n, word))
            break  # just find first occurrence for each a

print("Squares found (a, n, word):")
for s in squares:
    print(s)

# Also search for ALL positions for a=1,3,5
print("\nAll squares for a in {1,3,5} up to n=1000:")
for a in [1, 3, 5]:
    positions = []
    for n in range(1, min(1000, N - 2*a + 1)):
        ok = True
        for i in range(a):
            if flist[n-1+i] != flist[n-1+a+i]:
                ok = False
                break
        if ok:
            positions.append(n)
    print(f"a={a}: positions (first 20) = {positions[:20]}, total = {len(positions)}")
